using System;using System.IO;using ZwcadBatchPlot;
class Program { static void Check(bool ok,string reason){if(!ok)throw new Exception(reason);}static void Main(string[] args){string root=Path.Combine(args[0],Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string source=Path.Combine(root,"test.dwg");File.WriteAllBytes(source,new byte[]{1,2,3});using(var backup=new SignedPlotBackup(source)){Check(File.ReadAllBytes(backup.BackupPath).Length==3,"No original backup");backup.Complete();Check(!Directory.Exists(backup.Folder),"Normal backup not cleaned");}using(var backup=new SignedPlotBackup(source)){File.WriteAllBytes(source,new byte[]{4,5});bool rejected=false;try{backup.Complete();}catch(IOException){rejected=true;}Check(rejected&&File.Exists(backup.BackupPath)&&File.ReadAllBytes(source)[0]==4,"Concurrent file edit was overwritten or backup discarded");File.Delete(backup.BackupPath);File.Delete(Path.Combine(backup.Folder,"恢复说明.txt"));Directory.Delete(backup.Folder);}bool missing=false;try{using(var backup=new SignedPlotBackup(Path.Combine(root,"missing.dwg"))){} }catch(IOException){missing=true;}Check(missing,"Unsaved drawing accepted");Console.WriteLine("PASS verified backup, cleanup, concurrent original edit retains backup and never overwrites source, missing file rejection");}}
